const HABIT_DEFS=[
  {key:'skincare',name:'护肤'}, {key:'water',name:'每日喝水'}, {key:'exercise',name:'运动'},
  {key:'english',name:'英语'}, {key:'reading',name:'阅读'}, {key:'sleep',name:'早睡'}, {key:'ledger',name:'记账'}
];
const habitTemplateId=(key,weekday)=>`habit-${key}-${weekday}`;
const skincarePlans=['基础护肤与休息','基础护肤','补水面膜','基础护理','轻柔按摩','基础护肤','补水面膜'];
const exercisePlans=['休息与恢复','臀腿','核心','背部与体态','臀腿','核心与上肢','轻量有氧或拉伸'];
const defaultTemplates=Array.from({length:7},(_,weekday)=>HABIT_DEFS.map((h,habitOrder)=>{
  const base={id:habitTemplateId(h.key,weekday),habitKey:h.key,habit:h.name,weekday,reminder:'',note:'',reference:'',order:habitOrder};
  if(h.key==='skincare')return {...base,title:skincarePlans[weekday],amount:1,unit:'次',optional:[0,2,4,6].includes(weekday)};
  if(h.key==='water')return {...base,title:'喝水达标',amount:1500,unit:'ml',optional:false};
  if(h.key==='exercise')return {...base,title:exercisePlans[weekday],amount:weekday===0?0:weekday===6?30:[3,5].includes(weekday)?35:40,unit:weekday===0?'休息':'分钟',optional:[0,6].includes(weekday)};
  if(h.key==='english')return {...base,title:'完成当天英语学习',amount:0,unit:'次',optional:false};
  if(h.key==='reading')return {...base,title:'每天阅读 20 分钟',amount:20,unit:'分钟',optional:false};
  if(h.key==='sleep')return {...base,title:'按目标时间入睡',amount:0,unit:'次',optional:false};
  return {...base,title:'完成今日记账',amount:0,unit:'次',optional:false};
})).flat();

