function load(){try{const raw=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null');if(raw&&Number(raw.version||0)<DATA_VERSION&&!localStorage.getItem(MIGRATION_BACKUP_KEY))localStorage.setItem(MIGRATION_BACKUP_KEY,JSON.stringify(raw));return migrateState(raw);}catch{return structuredClone(seed);}}function save(){localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}
