document.addEventListener('change',async e=>{if(e.target.id!=='backupInput'||!e.target.files?.[0])return;try{const parsed=JSON.parse(await e.target.files[0].text());if(!parsed||typeof parsed!=='object'||Array.isArray(parsed))throw new Error('invalid');if(!confirm('导入备份将覆盖当前浏览器中的全部数据。建议先导出当前备份，确认继续吗？')){e.target.value='';return;}state=migrateState(parsed);save();render();toast('备份已恢复');}catch{toast('备份文件无法识别，请选择拾光导出的 JSON 文件');}finally{e.target.value='';}});
